import numpy as np
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
forms={'1-exp':lambda k:1-np.exp(-k*t),'tanh':lambda k:np.tanh(k*t),'t/(t+k)':lambda k:t/(t+k),'1-exp(-k t^2)':lambda k:1-np.exp(-k*t**2),'sqrt':lambda k:np.sqrt(t)*0+ (t/(k+t))}
def fit(G):
    cols=[G,P*G,P**2*G,P**3*G,np.ones_like(t),P,P**2,P**3]
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    return np.mean((y-X@c)**2)/np.var(y),c
best=[]
for name,f in forms.items():
    for k in np.linspace(0.05,3,60):
        n,c=fit(f(k)); best.append((n,name,k))
best.sort()
for b in best[:8]: print(b)
n,name,k=best[0]
n,c=fit(forms[name](k)); print(np.round(c,4))

